export type ParsedRedeemInstruction<
  TProgram extends string = typeof OUTCOME_TOKENS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Anyone who holds outcome tokens; no trader registration is needed. */
    holder: TAccountMetas[0];
    market: TAccountMetas[1];
    /** Either of the market's two mints. It decides which payout applies. */
    outcomeMint: TAccountMetas[2];
    /**
     * Any token account of the holder for the outcome mint; it need not be the
     * associated one.
     */
    holderOutcome: TAccountMetas[3];
    /**
     * account: a stable token account whose authority is the market. Left untyped so
     * that an unsettled market is reported as such, not as a vault that does not exist.
     */
    vault: TAccountMetas[4];
    /** Any stable token account of the holder. */
    holderStable: TAccountMetas[5];
    /** The vault's mint: the token program refuses the payout for any other. */
    stableMint: TAccountMetas[6];
    stableTokenProgram: TAccountMetas[7];
    outcomeTokenProgram: TAccountMetas[8];
  };
  data: RedeemInstructionData;
};

export function parseRedeemInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRedeemInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      holder: getNextAccount(),
      market: getNextAccount(),
      outcomeMint: getNextAccount(),
      holderOutcome: getNextAccount(),
      vault: getNextAccount(),
      holderStable: getNextAccount(),
      stableMint: getNextAccount(),
      stableTokenProgram: getNextAccount(),
      outcomeTokenProgram: getNextAccount(),
    },
    data: getRedeemInstructionDataDecoder().decode(instruction.data),
  };
}
